Let $A$ be a finitely presented $\Lambda$-module, and $e_{A} : A \longrightarrow A^{\ast\ast}$ the canonical evaluation map. Then there is an exact sequence
\begin{equation}\label{Eq:bidual}
\xymatrix
	{
	0 \ar[r]
	& \operatorname{\mathrm{Ext}}^{1}(\operatorname{\mathrm{Tr}} A, \Lambda) \ar[r]
	& A \ar[r]^{e_{A}}
	& A^{\ast\ast} \ar[r]
	& \operatorname{\mathrm{Ext}}^{2}(\operatorname{\mathrm{Tr}} A, \Lambda) \ar[r]
	& 0.
	}
\end{equation}
This is the $\Lambda$-component of the exact sequence of functors~\cite[Proposition 2.6 (a)]{AB}
\begin{equation}\label{D:ext}
\xymatrix@R1pt@C15pt
	{
	0 \ar[r]
	& \operatorname{\mathrm{Ext}}^{1}(\operatorname{\mathrm{Tr}} A, \hspace{0.04cm} \rule{2.4mm}{.4pt} \hspace{0.04cm} ) \ar[r]
	& A \otimes \hspace{0.04cm} \rule{2.4mm}{.4pt} \hspace{0.04cm}  \ar[r]^{\rho_{A}}
	& (A^{\ast}, \hspace{0.04cm} \rule{2.4mm}{.4pt} \hspace{0.04cm} ) \ar[r]
	& \operatorname{\mathrm{Ext}}^{2}(\operatorname{\mathrm{Tr}} A, \hspace{0.04cm} \rule{2.4mm}{.4pt} \hspace{0.04cm} ) \ar[r]
	& 0.
	}\footnote{The reader may check that  $\rho_{A}$ is the zeroth right-derived transformation for $A \otimes \hspace{0.04cm} \rule{2.4mm}{.4pt} \hspace{0.04cm} $.}
\end{equation}
When $A$ is not finitely presented, the sequence~\eqref{Eq:bidual} fails to be exact already for vector spaces over a field. Indeed, in that case the end terms vanish, forcing $\rho_{A}$, and hence $e_{A}$, to be an isomorphism, which is impossible since $A^{\ast\ast}$ has a larger dimension than~$A$.

{The Parallelogram Lemma}
Suppose, in the commutative diagram 
\[
\begin{tikzcd}
 A \ar[r] \ar[rd]
 & B \ar[d, "f"'] \ar[rd]
 \\
 & C \ar[r]
 & D
\end{tikzcd}
\]
the two peripheral compositions are zero.

\begin{enumerate}
 \item [a)] If $f$ is epic and the upper peripheral sequence $A \to B \to D$ is exact at $B$, then the lower peripheral sequence $A \to C \to D$ is exact at $C$.
 \item [b)] If $f$ is monic and the lower peripheral sequence $A \to C \to D$ is exact at $C$, then the upper peripheral sequence $A \to B \to D$ is exact at $B$.
\end{enumerate}

\hfill\label{T:co-fund-right}
\begin{enumerate}
 \item The right fundamental sequence~\eqref{D:rfs-co-fun} is a complex of functors, whose  homology is zero except, possibly, at the terms $R^{i}F$.

 \item If $F$ is half-exact, then the sequence is exact. 

 \item If $F$ is epi-preserving, then $\beta_{F}$ is epic.

 \item If $F$ is mono-preserving, then $\overline{F} = 0$ and $\rho_{F}$ is monic.

 \item $\rho_{F}$ is an isomorphism if and only if $F$ is left-exact.

\end{enumerate}

\label{EG:tensor-product}
Continue to assume that $\mathscr{A}$ is the category of left $\Lambda$-modules over a ring~$\Lambda$. Let $A$ be a right $\Lambda$-module and $F := A \otimes \hspace{0.04cm} \rule{2.4mm}{.4pt} \hspace{0.04cm} $. The sub-stabilization of $A \otimes \hspace{0.04cm} \rule{2.4mm}{.4pt} \hspace{0.04cm} $ is denoted by $A \operatorname{\overset{\rightharpoondown}{\otimes}} \hspace{0.04cm} \rule{2.4mm}{.4pt} \hspace{0.04cm} $ (see~\cite{MR-3, MR-2, MR-1}, where it was called the injective stabilization of the tensor product, for an extensive treatment of this concept). The initial segment of the right fundamental sequence~\eqref{D:rfs-co-fun} becomes
 \begin{equation}\label{Eq: 4-term for tensor product}
{0 \longrightarrow A \operatorname{\overset{\rightharpoondown}{\otimes}} \hspace{0.04cm} \rule{2.4mm}{.4pt} \hspace{0.04cm}  \longrightarrow A \otimes \hspace{0.04cm} \rule{2.4mm}{.4pt} \hspace{0.04cm}  \longrightarrow R^{0}(A \otimes \hspace{0.04cm} \rule{2.4mm}{.4pt} \hspace{0.04cm} )  \longrightarrow A \operatorname{\overset{\rightharpoondown}{\otimes}} (\Sigma \hspace{0.04cm} \rule{2.4mm}{.4pt} \hspace{0.04cm} ) \longrightarrow 0.}
\end{equation}
By the preceding theorem, it is exact. Evaluating it on  $\prescript{}{\Lambda}\Lambda$, we have another exact sequence (in the category of right $\Lambda$-modules)
 \[
 0 \longrightarrow \mathfrak{s}(A) \longrightarrow A  \longrightarrow R^{0}(A \otimes \hspace{0.04cm} \rule{2.4mm}{.4pt} \hspace{0.04cm} )(\Lambda) \longrightarrow A \operatorname{\overset{\rightharpoondown}{\otimes}} \Sigma \Lambda \longrightarrow 0,
 \] 
 where $\mathfrak{s}$ denotes the torsion radical introduced in~\cite{MR-2}.

\label{L:S=stab}
Suppose $(F^{i})_{i \in \mathbb{Z}}$ is a cohomological functor, i.e., an exact 
$\delta$-functor \textup{(}\cite[2.1]{Gr57}\textup{)}.\footnote{In this lemma, our definition of exact $\delta$-functor is a little more general than the quoted one. To wit, the integer $n$ can vary over the entire $\mathbb{Z}$.} Then, for each integer $n$,  the natural transformation $\theta^{n} : S^{1}F^{n} \longrightarrow \overline{F^{n + 1}}$ induced by $\delta^{n}$ is an isomorphism.

\hfill\label{T:co-fund-left}
\begin{enumerate}
 \item The left fundamental sequence~\eqref{D:lfs-co-fun} is a complex, whose homology is zero except possibly, at the terms $L_{i}F$.

 \item If $F$ is half-exact, then the sequence is exact. 

 \item If $F$ is mono-preserving, then $\alpha_{F}$ is monic.

 \item If $F$ is epi-preserving, then $\underline{F} = 0$ and $\lambda_{F}$ is epic.

 \item $\lambda_{F}$ is an isomorphism if and only if $F$ is right-exact.

\end{enumerate}

Let $F := (A, \hspace{0.04cm} \rule{2.4mm}{.4pt} \hspace{0.04cm} )$. It is easy to see that the quot-stabilization of $F$ is 
 $(A, \hspace{0.04cm} \rule{2.4mm}{.4pt} \hspace{0.04cm} )$ modulo projectives, i.e., $\underline{F} \simeq (\underline{A, \hspace{0.04cm} \rule{2.4mm}{.4pt} \hspace{0.04cm} })$ in the classical notation.\footnote{This is not a tautology but a fortuitous (if not unfortunate) coincidence; the underline notation for the Hom modulo projectives seems to predate the underline notation for the quot-stabilization. As we shall see later, the situation is dramatically different for contravariant functors.} The left fundamental sequence then becomes
\begin{equation}\label{E:co-4-term for hom}
\xymatrix
	{
	0 \ar[r]
	& (\underline{A, \hspace{0.04cm} \rule{2.4mm}{.4pt} \hspace{0.04cm} }) \circ  \Omega \ar[r]^{\alpha_{F}}          
	& L_{0}(A, \hspace{0.04cm} \rule{2.4mm}{.4pt} \hspace{0.04cm} ) \ar[r]^{\lambda_{A}}
	& (A, \hspace{0.04cm} \rule{2.4mm}{.4pt} \hspace{0.04cm} ) \ar[r]
	& (\underline{A, \hspace{0.04cm} \rule{2.4mm}{.4pt} \hspace{0.04cm} }) \ar[r]
	& 0.
	}
\end{equation}
Since $(A, \hspace{0.04cm} \rule{2.4mm}{.4pt} \hspace{0.04cm} )$ is left-exact, this sequence is exact.

\hfill\label{T:contra-4-term-rho}
\begin{enumerate}
 \item\label{I:ends} The right fundamental sequence~\eqref{D:rfs-contra-fun} is a complex, whose homology is zero, except, possibly, at the terms   $R_{i}F$.

 \item If $F$ is half-exact, then the sequence is exact.

 \item If $F$ carries monomorphisms to epimorphisms, then $\beta_{F}$ is epic.

 \item If $F$ carries epimorphisms to monomorphisms, then $\overline{F} = 0$ and $\rho_{F}$ is monic.

 \item\label{I:lex} $\rho_{F}$ is an isomorphism if and only if $F$ is left-exact.

\end{enumerate}

Suppose $F$ is finitely presented and that $\Lambda$ is left hereditary. Then the first row of the right fundamental sequence becomes
\begin{equation}
\begin{tikzcd}
	0 \ar[r]
	& \overline{F} \ar[r]
	& F \ar[r, "\rho_{F}"]
	& \big(\hspace{0.04cm} \rule{2.4mm}{.4pt} \hspace{0.04cm} , v(F)\big) \ar[r]
	& 0.
\end{tikzcd}
\end{equation}
If $F$ is half-exact, this sequence is exact, in fact, split exact.

\hfill \label{T:contra-fund-left}
\begin{enumerate}
 \item The left fundamental sequence~\eqref{D:lfs-contra-fun} is a complex, whose homology is zero except possibly, at the terms $L^{i}F$.

 \item If $F$ is half-exact, then the sequence is exact. 

 \item If $F$ carries epimorphisms to monomorphisms, then $\alpha_{F}$ is monic.

 \item If $F$ carries monomorphisms to epimorphisms, then $\underline{F} = 0$ and $\lambda_{F}$ is epic.

 \item $\lambda_{F}$ is an isomorphism if and only if $F$ is right-exact.

\end{enumerate}
